equation_of_line_from_two_points.src:
x1 = user_randint(min_coordinate, max_coordinate)
x2 = user_randint(min_coordinate, max_coordinate)
y1 = user_randint(min_coordinate, max_coordinate)
y2 = user_randint(min_coordinate, max_coordinate)
coeff_y = x2 - x1
coeff_x = y2 - y1
constant = y2 * coeff_y - x2 * coeff_x
gcd = _gcdEuclid(abs(coeff_x), abs(coeff_y))
if gcd != 1:
    if coeff_y > 0:
        coeff_y //= gcd
    if coeff_x > 0:
        coeff_x //= gcd
    if constant > 0:
        constant //= gcd
    if coeff_y < 0:
        coeff_y = -(-coeff_y // gcd)
    if coeff_x < 0:
        coeff_x = -(-coeff_x // gcd)
    if constant < 0:
        constant = -(-constant // gcd)
if coeff_y < 0:
    coeff_y = -coeff_y
    coeff_x = -coeff_x
    constant = -constant
if coeff_x in [1, -1]:
    if coeff_x == 1:
        coeff_x = ''
    else:
        coeff_x = '-'
if coeff_y in [1, -1]:
    if coeff_y == 1:
        coeff_y = ''
    else:
        coeff_y = '-'
problem = f'What is the equation of the line between points ({x1},{y1}) and ({x2},{y2}) in slope-intercept form?'
solution = ''
if coeff_x == 0:
    solution = str(coeff_y) + 'y = ' + str(constant)
elif coeff_y == 0:
    solution = str(coeff_x) + 'x = ' + str(-constant)
elif constant > 0:
    solution = str(coeff_y) + 'y = ' + str(coeff_x) + 'x + ' + str(constant)
else:
    solution = str(coeff_y) + 'y = ' + str(coeff_x) + 'x ' + str(constant)
return [problem, f'{solution}']

equation_of_line_from_two_points.tar:
var x1 = user_randint(min_coordinate, max_coordinate);
var x2 = user_randint(min_coordinate, max_coordinate);
var y1 = user_randint(min_coordinate, max_coordinate);
var y2 = user_randint(min_coordinate, max_coordinate);
var coeff_y = (x2 - x1);
var coeff_x = (y2 - y1);
var constant = y2 * coeff_y - x2 * coeff_x;
var gcd = _gcdEuclid(Math.abs(coeff_x), Math.abs(coeff_y));
if (gcd != 1) {
    if (coeff_y > 0) {
        coeff_y = Math.floor(coeff_y / gcd);
    }
    if (coeff_x > 0) {
        coeff_x = Math.floor(coeff_x / gcd);
    }
    if (constant > 0) {
        constant = Math.floor(constant / gcd);
    }
    if (coeff_y < 0) {
        coeff_y = -Math.floor(-coeff_y / gcd);
    }
    if (coeff_x < 0) {
        coeff_x = -Math.floor(-coeff_x / gcd);
    }
    if (constant < 0) {
        constant = -Math.floor(-constant / gcd);
    }
}
if (coeff_y < 0) {
    coeff_y = -coeff_y;
    coeff_x = -coeff_x;
    constant = -constant;
}
if ([-1, 1].includes(coeff_x)) {
    if (coeff_x === 1) {
        coeff_x = '';
    } else {
        coeff_x = '-';
    }
}
if ([-1, 1].includes(coeff_y)) {
    if (coeff_y === 1) {
        coeff_y = '';
    } else {
        coeff_y = '-';
    }
}
var problem = "What is the equation of the line between points (" + x1 + "," + y1 + ") and (" + x2 + "," + y2 + ") in slope-intercept form?";
var solution = "";
if (coeff_x === 0) {
    solution = coeff_y + "y = " + constant;
} else if (coeff_y === 0) {
    solution = coeff_x + "x = " + (-constant);
} else if (constant > 0) {
    solution = coeff_y + "y = " + coeff_x + "x + " + constant;
} else {
    solution = coeff_y + "y = " + coeff_x + "x " + constant;
}
return [problem, solution];
